const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length === 0 || input[0] === '') return;

    let ptr = 0;
    const n = parseInt(input[ptr++], 10);

    const matrix = [];
    let zeroRow = -1;
    let zeroCol = -1;

    for (let i = 0; i < n; i++) {
        const row = [];
        for (let j = 0; j < n; j++) {
            const val = parseInt(input[ptr++], 10);
            row.push(val);
            if (val === 0) {
                zeroRow = i;
                zeroCol = j;
            }
        }
        matrix.push(row);
    }

    // Escolhe uma linha que não contenha o zero para obter a soma mágica
    const completeRow = (zeroRow === 0) ? 1 : 0;
    let magicSum = 0;
    for (let j = 0; j < n; j++) {
        magicSum += matrix[completeRow][j];
    }

    let currentRowSum = 0;
    for (let j = 0; j < n; j++) {
        currentRowSum += matrix[zeroRow][j];
    }

    const missingValue = magicSum - currentRowSum;

    console.log(missingValue);
    console.log(zeroRow + 1);
    console.log(zeroCol + 1);
}

main();
